# /etc/unmask/nginx/honeypot.map
#
# bot 専用 path にアクセスしたら $serve_bot_challenge=1 を立て、 直後の通常 request
# (= 同じ TLS connection の再利用) を challenge に流す.
#
# 注意: ここの正規表現は「自社サイトに存在しない path」 のみを書くこと. 自社で実在する
# path を入れると正規ユーザが challenge に飛ばされる. apache log の 404 を rg で
# 「実 access があるのに自社で 提供してない path」 を抽出すると候補が出る.

# WordPress
"~*/wp-login\.php"          "1";
"~*/wp-admin"               "1";
"~*/xmlrpc\.php"            "1";
"~*/wp-content/themes/.*\.php" "1";

# 環境変数 / シークレット 漏洩 scan
"~*/\.env(?:$|/|\?)"        "1";
"~*/\.git/config"           "1";
"~*/\.aws/credentials"      "1";
"~*/config\.json"           "1";
"~*/secrets\.json"          "1";

# よくある CMS / 管理画面 探り
"~*/phpmyadmin"             "1";
"~*/myadmin"                "1";
"~*/adminer\.php"           "1";
"~*/admin\.php"             "1";
"~*/manage(?:r|ment)?/html" "1";

# よく shell upload 試行される拡張子
"~*\.php~$"                 "1";
"~*/shell\.php"             "1";
"~*/c99\.php"               "1";
"~*/r57\.php"               "1";

# CGI / Tomcat
"~*/cgi-bin/(?!debug-static$)"  "1";
"~*/manager/text"           "1";

# 探索 path (bot scanner の典型)
"~*/server-status"          "1";
"~*/actuator/(env|heapdump|trace)" "1";
